def july_winner(df):
    # Write your code here.
    pass

solution:
def july_winner(df):
    july = df[df['month'] == 7]
    if july.empty:
        return None
    totals = july.groupby('station')['rentals'].sum()
    best = totals.max()
    return min(totals[totals == best].index)

